                | Type::Usize
                | Type::ArrayU8(_)
                | Type::F32
                | Type::F64
                | Type::Bool
                | Type::String
                | Type::Bytes
                | Type::Str
                | Type::SliceU8
                | Type::StringMap
                | Type::OnceFunction
                | Type::OnceFunctionI64
