                        }
                        self.ty(return_type)?;
                    }
                    ExprKind::Call {
                        name,
                        type_arguments,
                        ..
                    } => {
                        self.name(name)?;
                        for ty in type_arguments {
                            self.ty(ty)?;
                        }
                    }
                    ExprKind::MethodCall {
                        method,
                        type_arguments,
                        ..
                    } => {
                        self.name(method)?;
                        for ty in type_arguments {
                            self.ty(ty)?;
                        }
                    }
                    ExprKind::SuperMethod { method, .. } => self.name(method)?,
                    ExprKind::ConstructRecord {
                        type_name,
                        type_arguments,
                        fields,
                        ..
                    }
                    | ExprKind::ConstructVariant {
                        type_name,
                        type_arguments,
                        fields,
                        ..
