                            self.ty(ty)?;
                        }
                        for f in fields {
                            self.name(&f.name)?;
                        }
                        if let ExprKind::ConstructVariant { case_name, .. } = &e.kind {
                            self.name(case_name)?;
                        }
                    }
                    ExprKind::UpdateRecord { fields, .. } => {
                        for f in fields {
                            self.name(&f.name)?;
                        }
                    }
                    ExprKind::Project { field, .. } => self.name(field)?,
                    ExprKind::Match { arms, .. } => {
                        for arm in arms {
                            self.pattern(&arm.pattern)?;
                        }
                    }
                    ExprKind::Block { statements, .. } => {
                        for s in statements {
                            match s {
                                Statement::Let { name, declared, .. } => {
                                    self.name(name)?;
                                    if let Some(ty) = declared {
                                        self.ty(ty)?;
                                    }
                                }
                                Statement::Assign { name, field, .. } => {
                                    self.name(name)?;
                                    if let Some(f) = field {
                                        self.name(&f.name)?;
                                    }
                                }
                                Statement::For { item, .. } | Statement::ForOwn { item, .. } => {
                                    self.name(item)?
                                }
                                Statement::ForBorrow { item, index, .. } => {
                                    self.name(item)?;
                                    if let Some(i) = index {
                                        self.name(&i.name)?;
                                    }
                                }
                                Statement::Unsafe { .. } | Statement::While { .. } => {}
                            }
                        }
                    }
                    ExprKind::LexicalExit { .. }
                    | ExprKind::Unary { .. }
                    | ExprKind::Binary { .. }
                    | ExprKind::If { .. }
                    | ExprKind::Try { .. }
                    | ExprKind::Yield { .. }
                    | ExprKind::Int(_)
                    | ExprKind::Int32(_)
                    | ExprKind::Char(_)
                    | ExprKind::Uint8(_)
                    | ExprKind::Usize(_)
                    | ExprKind::ArrayU8(_)
                    | ExprKind::RepeatArrayU8 { .. }
                    | ExprKind::Float32(_)
                    | ExprKind::Float64(_)
                    | ExprKind::Bool(_)
                    | ExprKind::String(_)
                    | ExprKind::BorrowedUtf8Literal(_) => {}
                }
            }
            if let Some(child) = e.child(index) {
                if self.expressions.len() + 2 > DEPTH {
                    return Err(refusal());
                }
                self.expressions.push((e, index + 1));
                self.expressions.push((child, 0));
            }
        }
        Ok(())
    }
}

#[cfg(test)]
