                    let complete = frames.pop().ok_or_else(refusal)?;
                    if facts.len() == capacity {
                        return Err(refusal());
                    }
                    facts.push(Fact {
                        module: complete.module,
                        declaration: complete.declaration,
                        owns: complete.owns,
                    });
                    if let Some(parent) = frames.last_mut() {
                        parent.owns |= complete.owns;
