        caller: &Program,
        authored: &'a BTreeMap<&'a str, AuthoredDeclaration<'a>>,
        programs: &'a [Program],
    ) -> Result<Self, Vec<Diagnostic>> {
        let mut remaining = WORK;
        Self::derive_with_work(caller, authored, programs, &mut remaining, None)
